create table d_ref_book(key_book_id string comment '账簿ID ',valid_startdate string comment '生效日期 ',valid_enddate string comment '失效日期 ',book_name string comment '账簿名称 ',description string comment '描述 ',desk string comment '柜台 ',department string comment '部门 ',company string comment '公司 ',created_datetime string comment '创建时间 ',created_by string comment '创建人 ',updated_datetime string comment '修改时间 ',updated_by string comment '修改人 ',short_name string comment '【AI】book短名',key_ctpty_id string comment '账簿归属主体对应交易对手id',enable_financial string comment '是否报送财务',enable_risk string comment '是否报送风控',enable_report string comment '是否启用报备',enable_settlement string comment '是否启用结算通知书',enable_confirmation string comment '是否启用交易确认书',enable_capital string comment '是否启用资金模块',enable_limit string comment '是否启用风险限额',data_time string comment '数据时间',enable_repeat_check string comment '是否启用二次复核',market_type string comment '场内外标识',mapping_wind_code string comment '【AI】映射Wind代码') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
